const input = $input.first().json;
const OWNER = input.githubOwner || 'bisco401';
const REPO = input.githubRepo || '6ixo';
const BRANCH = input.githubBranch || 'main';
const CSV_PATH = input.csvPath || 'data/scraped-listings.csv';
const TOKEN = input.githubToken;
const CRAWL4AI_URL = input.crawl4aiUrl || 'http://crawl4ai:11235/crawl';
const DEFAULT_STATUS = input.defaultImportStatus || 'published';
const HIDE_UNAVAILABLE = String(input.hideUnavailableListings ?? 'true').toLowerCase() === 'true';
const AVAILABILITY_MAX_ROWS = Math.max(0, Number(input.availabilityMaxRows || 24));
const AVAILABILITY_BATCH_SIZE = Math.max(1, Number(input.availabilityBatchSize || 6));
const AVAILABILITY_FRESH_HOURS = Math.max(0, Number(input.availabilityFreshHours || 12));
const nowIso = new Date().toISOString();
const nowMs = Date.parse(nowIso);

let sources = [];
try {
  sources = typeof input.sourcesJson === 'string' ? JSON.parse(input.sourcesJson || '[]') : (input.sourcesJson || []);
} catch (error) {
  throw new Error('sourcesJson is not valid JSON. Fix the Set Config Here node first.');
}

if (!TOKEN || TOKEN === 'PASTE_GITHUB_TOKEN_HERE') throw new Error('Paste your GitHub token into the Set Config Here node, or set GITHUB_TOKEN in n8n.');
if (!Array.isArray(sources) || !sources.length) throw new Error('Add at least one Kijiji source in sourcesJson.');

const csvHeaders = [
  'id','status','target_surface','app_category','app_subcategory','title','price_text','price_value','currency','city','country','seller','phone','description','image_urls','source_site','source_url','scraped_at','make','model','trim','year','condition','transmission','color','mileage_km','attributes','source_availability','source_availability_checked_at','source_http_status','source_unavailable_reason','source_last_seen_at','source_resolved_url'
];
const ghHeaders = { authorization: `Bearer ${TOKEN}`, accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28' };

const httpRequest = async (options) => {
  const request = {
    method: options.method || 'GET',
    uri: options.url,
    url: options.url,
    headers: options.headers || {},
    body: options.body,
    json: options.json === true,
    resolveWithFullResponse: true,
    simple: false
  };
  try {
    const response = await this.helpers.httpRequest(request);
    const status = response.statusCode || response.status || 200;
    return { status, ok: status >= 200 && status < 300, body: response.body ?? response };
  } catch (error) {
    const status = error.statusCode || error.status || error.response?.status || error.response?.statusCode || 500;
    const body = error.response?.body || error.response?.data || error.message || '';
    return { status, ok: status >= 200 && status < 300, body };
  }
};

const csvEscape = (value = '') => {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
};

const parseCsv = (text = '') => {
  const rows = [];
  let row = [];
  let cell = '';
  let quoted = false;
  const pushCell = () => { row.push(cell); cell = ''; };
  const pushRow = () => { pushCell(); if (row.some((v) => String(v || '').trim())) rows.push(row); row = []; };
  const inputText = String(text || '').replace(/^\uFEFF/, '');
  for (let i = 0; i < inputText.length; i += 1) {
    const char = inputText[i];
    const next = inputText[i + 1];
    if (quoted) {
      if (char === '"' && next === '"') { cell += '"'; i += 1; }
      else if (char === '"') quoted = false;
      else cell += char;
    } else if (char === '"') quoted = true;
    else if (char === ',') pushCell();
    else if (char === '\n') pushRow();
    else if (char !== '\r') cell += char;
  }
  if (cell || row.length) pushRow();
  const headers = (rows.shift() || csvHeaders).map((header) => String(header || '').trim());
  return rows.map((values) => headers.reduce((acc, header, index) => {
    if (header) acc[header] = values[index] || '';
    return acc;
  }, {}));
};

const toCsv = (rows = []) => [
  csvHeaders.join(','),
  ...rows.map((row) => csvHeaders.map((header) => csvEscape(row[header] || '')).join(','))
].join('\n') + '\n';

const normalizeUrl = (value = '') => {
  const raw = String(value || '').trim();
  if (!raw) return '';
  try {
    const url = new URL(raw, 'https://www.kijiji.ca');
    url.hash = '';
    return url.toString().replace(/\/$/, '');
  } catch {
    return raw.replace(/#.*$/, '').replace(/\/$/, '');
  }
};

const decodeHtml = (value = '') => String(value || '')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#34;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>');

const cleanText = (value = '') => decodeHtml(String(value || ''))
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const getGithubCsv = async () => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}?ref=${BRANCH}`;
  const res = await httpRequest({ url, headers: ghHeaders, json: true });
  if (res.status === 404) return { sha: null, text: csvHeaders.join(',') + '\n' };
  if (!res.ok) throw new Error(`Could not read ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  const body = typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
  return { sha: body.sha, text: Buffer.from(body.content || '', 'base64').toString('utf8') };
};

const putGithubCsv = async (text, sha) => {
  const url = `https://api.github.com/repos/${OWNER}/${REPO}/contents/${encodeURIComponent(CSV_PATH).replace(/%2F/g, '/')}`;
  const body = {
    message: 'Sync Kijiji Hamilton listings CSV',
    branch: BRANCH,
    content: Buffer.from(text, 'utf8').toString('base64'),
    ...(sha ? { sha } : {})
  };
  const res = await httpRequest({ url, method: 'PUT', headers: { ...ghHeaders, 'content-type': 'application/json' }, body, json: true });
  if (!res.ok) throw new Error(`Could not update ${CSV_PATH}: ${res.status} ${typeof res.body === 'string' ? res.body : JSON.stringify(res.body)}`);
  return typeof res.body === 'string' ? JSON.parse(res.body) : res.body;
};

const normalizeCrawlItems = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(normalizeCrawlItems);
  if (Array.isArray(value.results)) return value.results;
  if (Array.isArray(value.data)) return value.data;
  if (value.body) return normalizeCrawlItems(value.body);
  return [value];
};

const normalizeImageUrl = (value = '') => {
  const raw = decodeHtml(String(value || '').trim());
  if (!raw || /{{|}}|imageMessage|photoapparat|fb\/jacars/i.test(raw)) return '';
  try {
    const url = new URL(raw, 'https://www.kijiji.ca');
    if (!/^https?:$/i.test(url.protocol)) return '';
    if (/media.kijiji.ca/i.test(url.hostname) && url.searchParams.has('rule')) {
      url.searchParams.set('rule', 'kijijica-640-webp');
    }
    return url.toString();
  } catch {
    return raw.startsWith('http') ? raw : '';
  }
};

const imageUrlFromValue = (value) => {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap(imageUrlFromValue);
  if (typeof value === 'object') return imageUrlFromValue(value.contentUrl || value.url || value.src || value.image);
  const normalized = normalizeImageUrl(value);
  return normalized ? [normalized] : [];
};

const extractImageUrls = (html = '') => {
  const found = [];
  const seen = new Set();
  const add = (value) => {
    for (const imageUrl of imageUrlFromValue(value)) {
      if (!imageUrl || seen.has(imageUrl)) continue;
      seen.add(imageUrl);
      found.push(imageUrl);
    }
  };

  for (const block of extractScriptJson(html)) {
    const stack = Array.isArray(block) ? [...block] : [block];
    while (stack.length) {
      const item = stack.shift();
      if (!item || typeof item !== 'object') continue;
      if (item.image) add(item.image);
      if (item.contentUrl) add(item.contentUrl);
      if (Array.isArray(item.itemListElement)) stack.push(...item.itemListElement.map((entry) => entry?.item || entry));
      if (Array.isArray(item['@graph'])) stack.push(...item['@graph']);
    }
  }

  const mediaMatches = String(html || '').match(/https?:\/\/media\.kijiji\.ca[^"'\s<>]+/gi) || [];
  mediaMatches.forEach((url) => add(url.replace(/\u002F/g, '/').replace(/\u0026/g, '&')));
  return found.slice(0, 12);
};

const extractScriptJson = (html = '', id = '') => {
  const pattern = id
    ? new RegExp(`<script[^>]+id=["']${id}["'][^>]*>([\\s\\S]*?)<\\/script>`, 'i')
    : /<script[^>]*type=["']application\/(?:ld\+json|json)["'][^>]*>([\s\S]*?)<\/script>/gi;
  if (id) {
    const match = String(html || '').match(pattern);
    if (!match) return null;
    try { return JSON.parse(decodeHtml(match[1])); } catch { return null; }
  }
  return [...String(html || '').matchAll(pattern)].map((match) => {
    try { return JSON.parse(decodeHtml(match[1])); } catch { return null; }
  }).filter(Boolean);
};

const priceTextFromListing = (listing = {}) => {
  const amount = Number(listing?.price?.amount);
  const currency = String(listing?.price?.currency || 'CAD').trim() || 'CAD';
  if (!Number.isFinite(amount)) return '';
  const major = amount > 999 ? amount / 100 : amount;
  return currency === 'CAD' ? `CA$ ${major.toLocaleString('en-CA', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : `${currency} ${major}`;
};

const priceValueFromText = (value = '') => {
  const parsed = Number(String(value || '').replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) ? String(parsed) : '';
};

const normalizeCondition = (value = '') => {
  const text = String(value || '').toLowerCase();
  if (/like new/.test(text)) return 'like_new';
  if (/excellent/.test(text)) return 'excellent';
  if (/good/.test(text)) return 'good';
  if (/fair/.test(text)) return 'fair';
  if (/brand new|\bnew\b/.test(text)) return 'new';
  if (/used|pre-owned|preowned/.test(text)) return 'used';
  return '';
};

const phonePattern = /(?<!\d)(?:\+?1[\s.-]*)?(?:\(?((?:226|249|289|343|365|416|437|519|548|647|705|742|807|905))\)?[\s.-]*)(\d{3})[\s.-]*(\d{4})(?!\d)/g;
const phoneContextPattern = /\b(?:call|text|txt|phone|cell|tel|contact|whatsapp|message)\b/i;
const extractPhones = (...values) => {
  const found = [];
  const seen = new Set();
  for (const value of values) {
    const text = cleanText(value);
    let match;
    while ((match = phonePattern.exec(text))) {
      const raw = match[0];
      const start = Math.max(0, match.index - 45);
      const end = Math.min(text.length, match.index + raw.length + 25);
      const hasSeparator = /[\s().-]/.test(raw.trim());
      if (!hasSeparator && !phoneContextPattern.test(text.slice(start, end))) continue;
      const phone = `${match[1]}${match[2]}${match[3]}`;
      if (!seen.has(phone)) {
        seen.add(phone);
        found.push(phone);
      }
    }
  }
  return found.join(' | ');
};

const extractApolloListings = (html = '') => {
  const nextData = extractScriptJson(html, '__NEXT_DATA__');
  const apollo = nextData?.props?.pageProps?.__APOLLO_STATE__ || nextData?.props?.pageProps?.apolloState || {};
  return Object.values(apollo)
    .filter((entry) => entry && entry.__typename === 'StandardListing' && entry.url)
    .map((entry) => {
      const attrs = Array.isArray(entry?.attributes?.all) ? entry.attributes.all : [];
      const attrMap = new Map(attrs.map((item) => [String(item?.canonicalName || '').trim(), item]));
      const conditionAttr = attrMap.get('condition');
      const priceText = priceTextFromListing(entry);
      const description = cleanText(entry.description || '');
      const title = cleanText(entry.title || '');
      return {
        listingId: String(entry.id || '').trim(),
        title,
        description,
        sourceUrl: normalizeUrl(entry.url || ''),
        imageUrls: Array.isArray(entry.imageUrls) ? entry.imageUrls.flatMap(imageUrlFromValue).filter(Boolean) : [],
        priceText,
        priceValue: priceValueFromText(priceText),
        currency: String(entry?.price?.currency || 'CAD').trim() || 'CAD',
        city: cleanText(entry?.location?.name || ''),
        locationAddress: cleanText(entry?.location?.address || ''),
        seller: cleanText(entry?.posterInfo?.name || '') || 'Unknown',
        sellerId: String(entry?.posterInfo?.posterId || '').trim(),
        sellerType: cleanText(entry?.posterInfo?.sellerType || ''),
        condition: normalizeCondition((conditionAttr?.values || conditionAttr?.canonicalValues || [])[0] || `${title} ${description}`),
        postedAt: String(entry.activationDate || entry.sortingDate || '').trim(),
        sortingDate: String(entry.sortingDate || entry.activationDate || '').trim(),
        phone: extractPhones(title, description)
      };
    });
};

const extractJsonLdListings = (html = '') => {
  const blocks = extractScriptJson(html);
  const itemLists = blocks.flatMap((item) => Array.isArray(item) ? item : [item]).filter((item) => item?.['@type'] === 'ItemList' && Array.isArray(item.itemListElement));
  return itemLists.flatMap((list) => list.itemListElement.map((entry) => {
    const item = entry?.item || entry || {};
    const sourceUrl = normalizeUrl(item.url || '');
    const price = String(item?.offers?.price || '').trim();
    return {
      listingId: sourceUrl.match(/\/(\d+)(?:[/?#]|$)/)?.[1] || '',
      title: cleanText(item.name || ''),
      description: cleanText(item.description || ''),
      sourceUrl,
      imageUrls: item.image ? imageUrlFromValue(item.image) : [],
      priceText: price ? `$${price}` : '',
      priceValue: price,
      currency: String(item?.offers?.priceCurrency || 'CAD').trim() || 'CAD',
      city: '',
      locationAddress: '',
      seller: 'Unknown',
      sellerId: '',
      sellerType: '',
      condition: '',
      postedAt: '',
      sortingDate: '',
      phone: extractPhones(item.name, item.description)
    };
  })).filter((row) => row.title && row.sourceUrl);
};

const inferCategory = (listing = {}, source = {}) => {
  if (source.app_category || source.target_surface) {
    return {
      targetSurface: source.target_surface || (source.app_category === 'vehicles' ? 'vehicles' : 'marketplace'),
      appCategory: source.app_category || 'electronics',
      appSubcategory: source.app_subcategory || 'other'
    };
  }
  const text = `${listing.sourceUrl || ''} ${listing.title || ''} ${listing.description || ''}`.toLowerCase();
  if (/\b(tires?|rims?|wheels?|auto-parts|car-parts|vehicle-parts|parting-out|motorcycle|brake|transmission|engine)\b/.test(text)) {
    return { targetSurface: 'vehicles', appCategory: 'vehicles', appSubcategory: /\b(tires?|rims?|wheels?)\b/.test(text) ? 'tires_rims' : 'auto_parts' };
  }
  if (/\b(service|scrap metal|pick up|pickup|repair|cleaning|moving|delivery)\b/.test(text)) {
    return { targetSurface: 'marketplace', appCategory: 'services', appSubcategory: 'other' };
  }
  if (/\b(phone|iphone|samsung|laptop|tablet|camera|lens|stereo|speaker|yamaha|canon|dewalt|battery|charger|computer|headphone|tv)\b/.test(text)) {
    let subcategory = 'other';
    if (/\b(phone|iphone|samsung)\b/.test(text)) subcategory = 'phones_accessories';
    else if (/\b(laptop|tablet|computer)\b/.test(text)) subcategory = 'computers_tablets';
    else if (/\b(camera|lens|canon)\b/.test(text)) subcategory = 'cameras_photography';
    else if (/\b(stereo|speaker|yamaha|headphone)\b/.test(text)) subcategory = 'audio_headphones';
    return { targetSurface: 'marketplace', appCategory: 'electronics', appSubcategory: subcategory };
  }
  return { targetSurface: 'marketplace', appCategory: 'electronics', appSubcategory: 'other' };
};

const matchesCity = (listing, source) => {
  const strict = source.strict_city_match === true || String(source.strict_city_match || '').toLowerCase() === 'true';
  if (!strict) return true;
  const city = cleanText(source.city || '').toLowerCase();
  if (!city) return true;
  const hay = [listing.city, listing.locationAddress, listing.sourceUrl].map((value) => cleanText(value).toLowerCase()).join(' ');
  return hay.includes(city.toLowerCase());
};

const rowsFromCrawl = (crawlValue, activeSources) => {
  const crawlItems = normalizeCrawlItems(crawlValue || {});
  const crawlByUrl = new Map();
  for (const item of crawlItems) {
    const key = normalizeUrl(item.url || item.redirected_url || '');
    if (key) crawlByUrl.set(key, item);
  }
  const output = [];
  const sourceSummaries = [];
  for (const source of activeSources) {
    const listUrl = normalizeUrl(source.list_url || source.url || '');
    const crawlItem = crawlByUrl.get(listUrl) || Array.from(crawlByUrl.values()).find((entry) => normalizeUrl(entry.url || entry.redirected_url || '') === listUrl);
    const sourceName = source.name || source.city || listUrl;
    if (!crawlItem) {
      sourceSummaries.push({ source: sourceName, status: 'failed', fetched: 0, error: 'Crawl4AI did not return this URL.' });
      continue;
    }
    const raw = crawlItem.html || crawlItem.cleaned_html || crawlItem.fit_html || crawlItem.markdown?.raw_markdown || crawlItem.markdown || crawlItem.fit_markdown || '';
    if (!raw) {
      sourceSummaries.push({ source: sourceName, status: 'failed', fetched: 0, error: crawlItem.error_message || 'No HTML returned.' });
      continue;
    }
    let listings = extractApolloListings(raw);
    if (!listings.length) listings = extractJsonLdListings(raw);
    const maxListings = Math.max(1, Number(source.max_listings || 50));
    const seen = new Set();
    const normalized = listings
      .filter((listing) => listing && listing.title && listing.sourceUrl && !seen.has(listing.sourceUrl) && (seen.add(listing.sourceUrl) || true))
      .filter((listing) => matchesCity(listing, source))
      .filter((listing) => String(listing.phone || '').trim())
      .slice(0, maxListings)
      .map((listing) => {
        const inferred = inferCategory(listing, source);
        const id = listing.listingId ? `kijiji-${listing.listingId}` : `kijiji-${Math.abs([...listing.sourceUrl].reduce((a, c) => ((a << 5) - a + c.charCodeAt(0)) | 0, 0))}`;
        return {
          id,
          status: source.default_status || DEFAULT_STATUS,
          target_surface: inferred.targetSurface,
          app_category: inferred.appCategory,
          app_subcategory: inferred.appSubcategory,
          title: listing.title,
          price_text: listing.priceText,
          price_value: listing.priceValue,
          currency: listing.currency || 'CAD',
          city: listing.city || source.city || '',
          country: source.country || 'Canada',
          seller: listing.seller || 'Unknown',
          phone: listing.phone || '',
          description: listing.description,
          image_urls: (listing.imageUrls || []).join('|'),
          source_site: 'Kijiji',
          source_url: listing.sourceUrl,
          scraped_at: listing.sortingDate || listing.postedAt || nowIso,
          make: '',
          model: '',
          trim: '',
          year: String(`${listing.title} ${listing.description}`.match(/\b(19|20)\d{2}\b/)?.[0] || ''),
          condition: listing.condition || '',
          transmission: '',
          color: '',
          mileage_km: '',
          attributes: JSON.stringify({ parser: 'kijiji_crawl4ai_sync', listUrl, sourceName, locationAddress: listing.locationAddress, sellerId: listing.sellerId, sellerType: listing.sellerType }),
          source_availability: 'active',
          source_availability_checked_at: nowIso,
          source_http_status: String(crawlItem.status_code || crawlItem.statusCode || 200),
          source_unavailable_reason: '',
          source_last_seen_at: nowIso,
          source_resolved_url: listing.sourceUrl
        };
      });
    output.push(...normalized);
    sourceSummaries.push({ source: sourceName, status: normalized.length ? 'success' : 'empty', fetched: normalized.length });
  }
  return { rows: output, sourceSummaries };
};

const crawlDetailUrls = async (urls) => {
  const results = new Map();
  for (let i = 0; i < urls.length; i += AVAILABILITY_BATCH_SIZE) {
    const batch = urls.slice(i, i + AVAILABILITY_BATCH_SIZE);
    const response = await httpRequest({
      url: CRAWL4AI_URL,
      method: 'POST',
      json: true,
      body: {
        urls: batch,
        browser_config: { headless: true, viewport: { width: 1280, height: 1800 }, verbose: false },
        crawler_config: { stream: false, cache_mode: 'bypass', wait_until: 'domcontentloaded', wait_for: 'css:body', page_timeout: 20000, delay_before_return_html: 0.5, remove_overlay_elements: true, remove_consent_popups: true }
      }
    });
    const items = normalizeCrawlItems(response.body || response);
    for (let index = 0; index < items.length; index += 1) {
      const item = items[index] || {};
      const fallbackUrl = batch[index] || '';
      const keys = [item.url, item.redirected_url, fallbackUrl].map(normalizeUrl).filter(Boolean);
      const raw = item.html || item.cleaned_html || item.fit_html || item.markdown?.raw_markdown || item.markdown || item.fit_markdown || '';
      const text = cleanText(raw).toLowerCase();
      const statusCode = Number(item.status_code || item.statusCode || item.response?.status || response.status || 0);
      let availability = 'unknown';
      let reason = '';
      if (statusCode === 404 || statusCode === 410) {
        availability = 'gone';
        reason = `HTTP ${statusCode}`;
      } else if (/\b(sold|item has sold|listing sold)\b/i.test(text)) {
        availability = 'sold';
        reason = 'Source page says sold.';
      } else if (/ad is no longer available|listing is no longer available|no longer available|has been removed|ad has expired|this ad is unavailable|page not found|does not exist/i.test(text)) {
        availability = 'unavailable';
        reason = 'Source page says removed, expired, or unavailable.';
      } else if (raw && /kijiji/i.test(raw)) {
        availability = 'active';
      } else if (item.error_message || item.error) {
        reason = String(item.error_message || item.error || '').slice(0, 160);
      } else if (!raw) {
        reason = 'No detail page content returned.';
      }
      const result = { availability, reason, statusCode: statusCode ? String(statusCode) : '', resolvedUrl: normalizeUrl(item.redirected_url || item.url || fallbackUrl), imageUrls: extractImageUrls(raw) };
      keys.forEach((key) => results.set(key, result));
    }
  }
  return results;
};

const activeSources = sources.filter((source) => source && source.enabled !== false);
const existing = await getGithubCsv();
const existingRows = parseCsv(existing.text);
const rowsByUrl = new Map(existingRows.map((row) => [normalizeUrl(row.source_url || ''), row]).filter(([key]) => key));

const { rows: scrapedRows, sourceSummaries } = rowsFromCrawl(input.crawl4aiResult || input, activeSources);
const scrapedDetailUrls = scrapedRows.map((row) => normalizeUrl(row.source_url || '')).filter(Boolean).slice(0, AVAILABILITY_MAX_ROWS);
const scrapedDetailsByUrl = scrapedDetailUrls.length ? await crawlDetailUrls.call(this, scrapedDetailUrls) : new Map();
for (const row of scrapedRows) {
  const detail = scrapedDetailsByUrl.get(normalizeUrl(row.source_url || ''));
  if (detail?.imageUrls?.length) {
    const currentImages = String(row.image_urls || '').split('|').map(normalizeImageUrl).filter(Boolean);
    row.image_urls = Array.from(new Set([...detail.imageUrls, ...currentImages])).slice(0, 12).join('|');
  }
}
let inserted = 0;
let updated = 0;
for (const row of scrapedRows) {
  const key = normalizeUrl(row.source_url || '');
  if (!key) continue;
  const previous = rowsByUrl.get(key) || {};
  if (previous.source_url) updated += 1;
  else inserted += 1;
  rowsByUrl.set(key, { ...previous, ...row });
}

const scrapedUrlSet = new Set(scrapedRows.map((row) => normalizeUrl(row.source_url || '')).filter(Boolean));
const configuredCities = activeSources.map((source) => cleanText(source.city || '').toLowerCase()).filter(Boolean);
const checkedAgeHours = (row) => {
  const checkedAt = Date.parse(row.source_availability_checked_at || '');
  if (!Number.isFinite(checkedAt)) return Number.POSITIVE_INFINITY;
  return Math.max(0, (nowMs - checkedAt) / 36e5);
};
const shouldCheckRow = (row) => {
  const url = normalizeUrl(row.source_url || '');
  if (!/kijiji\.ca/i.test(url) && String(row.source_site || '').toLowerCase() !== 'kijiji') return false;
  if (!configuredCities.length) return true;
  const hay = [row.city, row.source_url, row.attributes].map((value) => cleanText(value).toLowerCase()).join(' ');
  return configuredCities.some((city) => hay.includes(city));
};

const availabilityCandidates = Array.from(rowsByUrl.values())
  .filter(shouldCheckRow)
  .filter((row) => {
    const url = normalizeUrl(row.source_url || '');
    if (scrapedUrlSet.has(url)) return false;
    return checkedAgeHours(row) >= AVAILABILITY_FRESH_HOURS;
  })
  .sort((a, b) => checkedAgeHours(b) - checkedAgeHours(a) || String(b.scraped_at || '').localeCompare(String(a.scraped_at || '')))
  .slice(0, AVAILABILITY_MAX_ROWS);
const candidateUrls = availabilityCandidates.map((row) => normalizeUrl(row.source_url || '')).filter(Boolean);
const availabilityByUrl = candidateUrls.length ? await crawlDetailUrls.call(this, candidateUrls) : new Map();
let active = 0;
let sold = 0;
let hidden = 0;
let unavailable = 0;
let unknown = 0;
for (const row of availabilityCandidates) {
  const key = normalizeUrl(row.source_url || '');
  const result = availabilityByUrl.get(key);
  if (!result) continue;
  row.source_availability = result.availability;
  row.source_availability_checked_at = nowIso;
  row.source_http_status = result.statusCode;
  row.source_unavailable_reason = result.reason;
  row.source_resolved_url = result.resolvedUrl || row.source_url;
  if (result.availability === 'active') {
    row.source_last_seen_at = nowIso;
    active += 1;
  } else if (result.availability === 'sold') {
    sold += 1;
  } else if (['unavailable', 'gone'].includes(result.availability)) {
    unavailable += 1;
    if (HIDE_UNAVAILABLE) {
      row.status = 'rejected';
      hidden += 1;
    }
  } else {
    unknown += 1;
  }
}

const nextRows = Array.from(rowsByUrl.values()).sort((a, b) => String(b.scraped_at || '').localeCompare(String(a.scraped_at || '')));
await putGithubCsv(toCsv(nextRows), existing.sha);

return [{
  json: {
    status: 'completed',
    csvPath: CSV_PATH,
    sources: sourceSummaries,
    scraped: scrapedRows.length,
    inserted,
    updated,
    detailImagesChecked: scrapedDetailUrls.length,
    availabilityChecked: availabilityCandidates.length,
    availabilityFreshHours: AVAILABILITY_FRESH_HOURS,
    active,
    sold,
    unavailable,
    unknown,
    hidden,
    hideUnavailableListings: HIDE_UNAVAILABLE
  }
}];
